def with_tax(price, rate=0.2):
    return round(price * (1 + rate), 2)

print(with_tax(50))
print(with_tax(50, 0.1))

def label(name, prefix="Mr", suffix=""):
    parts = [prefix, name]
    if suffix:
        parts.append(suffix)
    return " ".join(parts)

print(label("Lovelace"))
print(label("Lovelace", prefix="Dr"))
print(label("Lovelace", suffix="PhD", prefix="Prof"))

def biggest_gap(*numbers):
    if not numbers:
        return 0
    return max(numbers) - min(numbers)

print(biggest_gap(4, 19, 7))
print(biggest_gap(5))
print(biggest_gap())

