def price_report(*prices, currency="EUR", decimals=2, **tags):
    if prices:
        total = sum(prices)
        avg = total / len(prices)
        text = f"{len(prices)} items, total {total:.{decimals}f} {currency}, avg {avg:.{decimals}f} {currency}"
    else:
        text = "0 items"
    for key in sorted(tags):
        text += f" | {key}={tags[key]}"
    return text

print(price_report(120.5, 99.25, 80))
print(price_report(10, 20, currency="USD", decimals=0, shop="A", day="Mon"))
print(price_report(region="EU"))

rows = [{"date": "2025-04-01", "category": "food", "amount": 12.5}, {"date": "2025-04-02", "category": "fun", "amount": 8, "note": "cinema"}]

def build_line(date, category, amount, note=""):
    line = f"{date} | {category} | {amount:.2f}"
    if note:
        line += f" | {note}"
    return line

for row in rows:
    print(build_line(**row))
print(build_line(*["2025-04-03", "rent", 800]))
